function e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function db(): PDO { global $cfg; static $pdo=null; if(!$pdo){$dsn='mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4';$pdo=new PDO($dsn,$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}return $pdo; }
function q(string $sql,array $args=[]): array {$s=db()->prepare($sql);$s->execute($args);return $s->fetchAll();}
function x(string $sql,array $args=[]): int {$s=db()->prepare($sql);$s->execute($args);return (int)db()->lastInsertId();}
