function safehttpurl(string $url): bool {
    if(strlen($url)>2048 || !filter_var($url,FILTER_VALIDATE_URL)) return false;
    $parts=parse_url($url); $scheme=strtolower((string)($parts['scheme']??'')); $host=strtolower(rtrim((string)($parts['host']??''),'.'));
    if(!in_array($scheme,['http','https'],true) || !$host || isset($parts['user']) || isset($parts['pass'])) return false;
    if($host==='localhost' || str_ends_with($host,'.localhost') || str_ends_with($host,'.local') || str_ends_with($host,'.internal')) return false;
    $ips=filter_var($host,FILTER_VALIDATE_IP)?[$host]:[(gethostbyname($host)!==$host?gethostbyname($host):'')];
    foreach($ips as $ip) if($ip!=='' && !filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)) return false;
    return true;
}
