if($p==='admin'){needadmin();renderhead('en','Admin · WORLD PULSE','',null,true);$counts=[];foreach(['published','new','expired','rejected'] as $s)$counts[$s]=q('SELECT COUNT(*) c FROM articles WHERE status=?',[$s])[0]['c'];echo '<div class="adminhead"><h1>WORLD PULSE · Admin</h1><form method="post" action="?p=logout"><input type="hidden" name="csrf" value="'.e(csrf()).'"><button type="submit">Logout</button></form></div><section class="panel"><h2>Pipeline</h2><p>Published: '.$counts['published'].' · New: '.$counts['new'].'</p><form method="post" action="?p=run"><input type="hidden" name="csrf" value="'.e(csrf()).'"><button>Collect RSS and process news now</button></form><p class="muted">On InfinityFree this runs only when you press the button or an admin page request triggers it; there is no background scheduler.</p></section><section class="panel"><h2>Add RSS source</h2><form method="post" action="?p=addsource"><input type="hidden" name="csrf" value="'.e(csrf()).'"><div class="formrow"><input name="name" placeholder="Source name" required><input name="url" placeholder="https://example.com/rss.xml" required><select name="category">';foreach($GLOBALS['cats'] as $k=>$v)echo '<option value="'.e($k).'">'.e($v).'</option>';echo '</select><button>Add source</button></div></form></section><section class="panel"><h2>Sources</h2><table><tr><th>Name</th><th>URL</th><th>Active</th><th>Action</th></tr>';foreach(q('SELECT * FROM sources ORDER BY id') as $s){echo '<tr><td>'.e($s['name']).'</td><td>'.e($s['url']).'</td><td>'.($s['active']?'Yes':'No').'</td><td><form method="post" action="?p=toggle"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="id" value="'.$s['id'].'"><button>Toggle</button></form></td></tr>';}echo '</table></section><section class="panel"><h2>Recent logs</h2><table><tr><th>Date</th><th>Level</th><th>Message</th></tr>';foreach(q('SELECT * FROM logs ORDER BY id DESC LIMIT 20') as $l)echo '<tr><td>'.e($l['ts']).'</td><td>'.e($l['level']).'</td><td>'.e($l['msg']).'</td></tr>';echo '</table></section>';renderfoot();exit;}
if(in_array($p,['run','addsource','toggle'],true)){needadmin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit; }checkcsrf();try{if($p==='run')$message=runpipeline();elseif($p==='addsource'){ $url=(string)($_POST['url']??'');if(!safehttpurl($url))throw new RuntimeException('Invalid or non-public RSS URL');x('INSERT IGNORE INTO sources(name,url,category) VALUES(?,?,?)',[cleantext((string)$_POST['name'],110),$url,array_key_exists($_POST['category']??'world',$cats)?$_POST['category']:'world']);$message='Source added';}else{x('UPDATE sources SET active=1-active WHERE id=?',[(int)$_POST['id']]);$message='Source updated';}$_SESSION['flash']=$message;}catch(Throwable $e){logmsg('admin','error',$e->getMessage());$_SESSION['flash']='Error: '.$e->getMessage();}header('Location: ?p=admin');exit;}
if($p==='article'){$slug=(string)($_GET['slug']??'');$a=q("SELECT * FROM articles WHERE slug=? AND status='published'",[$slug])[0]??null;if(!$a){http_response_code(404);echo 'Not found';exit;}renderhead($lang,titleof($a,'title',$lang),titleof($a,'seo',$lang),$a);echo '<article class="story"><span class="cat">'.e($cats[$a['category']]??'World').'</span><h1>'.e(titleof($a,'title',$lang)).'</h1><time>'.e($a['published_at']).' UTC</time>'.(gallery((int)$a['id'],titleof($a,'title',$lang))?:cover($a['category'])).'<p class="lede">'.nl2br(e(titleof($a,'summary',$lang))).'</p><h3>'.e($ui[$lang]['sources']).'</h3><ul class="srcs">';foreach(q('SELECT DISTINCT s.name,r.link FROM raw_items r JOIN sources s ON s.id=r.source_id WHERE r.article_id=?',[$a['id']]) as $s)echo '<li><a target="_blank" rel="nofollow noopener" href="'.e($s['link']).'">'.e($s['name']).'</a></li>';echo '</ul></article>';renderfoot();exit;}
$cat=$_GET['cat']??'';$where="status='published'";$args=[];if(isset($cats[$cat])){$where.=' AND category=?';$args[]=$cat;} $arts=q('SELECT * FROM articles WHERE '.$where.' ORDER BY published_at DESC LIMIT 40',$args);$breaking=q("SELECT * FROM articles WHERE status='published' AND breaking=1 AND published_at>=? ORDER BY published_at DESC LIMIT 3",[ago(6)]);renderhead($lang,$cfg['site_name'],$ui[$lang]['tag']);if(!empty($_SESSION['flash'])){echo '<p class="ok">'.e($_SESSION['flash']).'</p>';unset($_SESSION['flash']);}foreach($breaking as $b)echo '<a class="brk" href="?p=article&slug='.e($b['slug']).'&lang='.$lang.'"><b>'.e($ui[$lang]['breaking']).'</b> '.e(titleof($b,'title',$lang)).'</a>';if(!$arts)echo '<p class="panel">'.e($ui[$lang]['empty']).'</p>';if($arts){$lead=array_shift($arts);echo '<article class="lead"><a href="?p=article&slug='.e($lead['slug']).'&lang='.$lang.'">'.(gallery((int)$lead['id'],titleof($lead,'title',$lang))?:cover($lead['category'])).'</a><div><span class="cat">'.e($lang==='ar'?($catAr[$lead['category']]??'عالم'):($cats[$lead['category']]??'World')).'</span><h1><a href="?p=article&slug='.e($lead['slug']).'&lang='.$lang.'">'.e(titleof($lead,'title',$lang)).'</a></h1><p>'.e(titleof($lead,'summary',$lang)).'</p><time>'.e($lead['published_at']).' UTC · '.(int)$lead['n_sources'].' '.e($ui[$lang]['sources']).'</time></div></article><section class="grid">';foreach($arts as $a)echo '<article><span class="cat">'.e($cats[$a['category']]??'World').'</span><h2><a href="?p=article&slug='.e($a['slug']).'&lang='.$lang.'">'.e(titleof($a,'title',$lang)).'</a></h2><time>'.e($a['published_at']).'</time></article>';echo '</section>'; }renderfoot();
